/* Local design prototype. All records are synthetic; no broker API is called. */
const paths={
  grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',
  users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M16 3.13a4 4 0 0 1 0 7.75',
  topic:'m12 3 9 5-9 5-9-5 9-5z M3 12l9 5 9-5 M3 16l9 5 9-5',
  shield:'M12 3 3 7v5c0 5 9 9 9 9s9-4 9-9V7l-9-4z m-4 9 3 3 5-6',
  plug:'M8 3v5 M16 3v5 M5 8h14 M7 8v5a5 5 0 0 0 10 0V8 M12 18v4',
  settings:'M4 7h16 M4 17h16 M8 4v6 M16 14v6',
  rule:'M5 3h14v18H5z M8 7h8 M8 11h8 M8 15h4',
  log:'M4 4h16v16H4z M8 8l3 3-3 3 M13 15h3',
  search:'m21 21-5-5 M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14',
  refresh:'M20 7v5h-5 M4 17v-5h5 M6.1 6a8 8 0 0 1 13.2 2 M17.9 18A8 8 0 0 1 4.7 16',
  arrow:'M5 12h14 m-5-5 5 5-5 5',
  up:'M12 20V4 m-6 6 6-6 6 6',
  down:'M12 4v16 m-6-6 6 6 6-6',
  server:'M3 4h18v6H3z M3 14h18v6H3z M7 7h.01 M7 17h.01',
  cpu:'M7 7h10v10H7z M9 1v3 M15 1v3 M9 20v3 M15 20v3 M1 9h3 M1 15h3 M20 9h3 M20 15h3',
  memory:'M3 6h18v12H3z M7 9v6 M11 9v6 M15 9v6 M19 9v6 M6 18v3 M10 18v3 M14 18v3 M18 18v3',
  disk:'M4 6c0-4 16-4 16 0s-16 4-16 0z M4 6v12c0 4 16 4 16 0V6 M4 12c0 4 16 4 16 0',
  eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z M15 12a3 3 0 1 0-6 0 3 3 0 0 0 6 0',
  clock:'M12 8v5l3 2 M21 12a9 9 0 1 0-18 0 9 9 0 0 0 18 0',
  close:'M6 6l12 12 M6 18 18 6',
  copy:'M8 8h12v13H8z M16 8V3H3v13h5',
  chevron:'m9 5 7 7-7 7',
  certificate:'M6 3h12v13H6z M9 7h6 M9 10h4 M9 16v5l3-2 3 2v-5',
  info:'M12 11v6 M12 7h.01 M21 12a9 9 0 1 0-18 0 9 9 0 0 0 18 0',
  menu:'M4 6h16 M4 12h16 M4 18h16'
};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.grid}"/></svg>`;
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const badge=(text,color='gray',dot=false)=>`<span class="badge ${color}">${dot?'<span class="status-dot"></span>':''}${text}</span>`;
const nav=[['工作台',[['overview','grid','运行概览'],['connections','users','连接与会话','8.4k'],['topics','topic','主题与消息']]],['管理',[['security','shield','认证与授权'],['listeners','plug','连接入口'],['configuration','settings','实例配置'],['logs','log','事件记录']]],['扩展',[['rules','rule','规则引擎','规划中']]]];
const clients=Array.from({length:12},(_,i)=>({
  id:['sensor-sh-0018','sensor-sh-0024','sensor-hz-0102','platform-ingest-01','ops-monitor-01','sensor-sz-0039','sensor-hz-0117','platform-ingest-02','sensor-sh-0086','sensor-sz-0042','sensor-hz-0063','sensor-sh-0011'][i],
  version:i%3===0?'3.1.1':'5.0',online:i<10,ip:`10.0.${i<4?'1':'2'}.${[81,92,108,36,20,117,96,37,89,124,72,68][i]}`,
  user:i===4?'ops-reader':(i===3||i===7)?'platform-api':'device-service',
  subscriptions:[4,3,5,12,8,4,3,12,5,3,4,2][i],
  duration:['02:36:18','02:28:46','01:52:03','1天 06:14','1天 03:42','00:47:12','00:39:56','1天 06:10','00:26:33','00:18:42','—','—'][i],
  incoming:[18426,12703,15981,24891,0,7291,5408,21486,3209,2038,8240,3960][i],outgoing:[213,176,301,84916,41826,94,108,73819,76,45,92,41][i],
  queued:i<10?0:i===10?12:3
}));
const topics=[
 ['devices/sensor-sh-0018/telemetry','device-service','128 B',14,'实时遥测'],
 ['devices/sensor-hz-0102/telemetry','device-service','256 B',8,'实时遥测'],
 ['devices/sensor-sz-0039/status','device-service','64 B',6,'设备状态'],
 ['alerts/temperature','platform-api','192 B',3,'温度告警'],
 ['platform/commands/device','platform-api','128 B',12,'设备指令'],
 ['devices/sensor-sh-0024/status','device-service','64 B',4,'设备状态']
];
const events=[['14:32:08','INFO','client.connected','sensor-sh-0018','MQTT5 · WSS · user:device-service'],['14:31:56','INFO','session.resumed','sensor-hz-0102','恢复持久会话，待确认消息 2 条'],['14:31:42','WARN','auth.rate_limited','10.0.2.108','超过认证令牌预算，返回 CONNACK 0x89'],['14:31:20','INFO','tls.client_verified','sensor-sh-0024','客户端证书通过校验'],['14:30:54','INFO','client.disconnected','sensor-hz-0063','异常断连，会话转为离线'],['14:30:26','INFO','storage.committed','sessions.sqlite','会话状态已提交'],['14:29:38','WARN','tls.client_rejected','10.0.2.163','客户端未提供受信任证书'],['14:28:11','INFO','listener.started','WSS :8084','单监听 · TLS1.2 / TLS1.3']];
const state={page:'overview',range:'1h',tab:'all',search:'',version:'all',topicTab:'active',securityTab:'users',logLevel:'all',pageNumber:1};
let previousFocus=null,toastTimer;
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2200);}
function pageHeading(eyebrow,title,subtitle,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`;}
function panelTitle(title,extra='',sub=''){return `<div class="panel-header"><h2 class="panel-title">${title}${sub?`<span class="panel-subtitle">${sub}</span>`:''}</h2>${extra}</div>`;}
function spark(i){const pts=Array.from({length:20},(_,j)=>`${j*4},${19-Math.sin(j*.54+i)*4-j*.4+(j%4)*1.5}`).join(' ');return `<svg class="spark" viewBox="0 0 78 28" aria-hidden="true"><polyline points="${pts}" fill="none" stroke="${i===2?'#87a6cc':'#7eaf99'}" stroke-width="1.5" stroke-linejoin="round"/></svg>`;}
function metrics(){return `<div class="cards">${[
 ['在线连接','8,462','','↑ 5.2%','较上一小时','users'],['消息入站','12,840','条/s','↑ 8.4%','较上一小时','down'],['消息出站','18,296','条/s','↑ 6.1%','较上一小时','up'],['持久会话','9,351','','在线 8,462','离线 889','disk']
 ].map((m,i)=>`<div class="card metric"><div class="metric-label">${m[0]}<span class="metric-symbol">${icon(m[5])}</span></div><div class="metric-number">${m[1]}<small>${m[2]}</small></div><div class="metric-foot"><span class="metric-trend">${m[3]}</span><span>${m[4]}</span></div>${spark(i)}</div>`).join('')}</div>`;}
function trafficSamples(){
 const raw=Array.from({length:61},(_,i)=>{const bump=i>23&&i<37?Math.sin((i-23)/14*Math.PI)*1.9:0;return [6.3+i*.072+Math.sin(i*.48)*.55+Math.cos(i*1.5)*.32+bump,10.5+i*.08+Math.sin(i*.39)*.7+Math.cos(i*.8)*.42+bump*1.3];});
 const end=raw.at(-1),last=state.range==='1h'?[12.84,18.296]:[10.26,15.84];
 return raw.map(v=>[v[0]/end[0]*last[0],v[1]/end[1]*last[1]]);
}
function chart(){
 const data=trafficSamples();
 const xy=(v,i)=>`${42+i*9.3},${160-v*7.7}`;const points=series=>data.map((v,i)=>xy(v[series],i)).join(' ');
 const labels=state.range==='1h'?['13:30','13:40','13:50','14:00','14:10','14:20','14:30']:['10/29 14:30','18:30','22:30','10/30 02:30','06:30','10:30','14:30'];
 return `<svg viewBox="0 0 628 194" preserveAspectRatio="none" role="img" aria-label="演示消息吞吐趋势，绿色为入站，蓝色为出站"><defs><linearGradient id="area-green" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#53a385" stop-opacity=".12"/><stop offset="1" stop-color="#53a385" stop-opacity=".005"/></linearGradient></defs>${[0,5,10,15,20].map(v=>`<line x1="42" y1="${160-v*7.7}" x2="601" y2="${160-v*7.7}" stroke="#edf1f3" stroke-dasharray="3 4"/><text x="30" y="${163-v*7.7}" text-anchor="end" fill="#adb7bf" font-size="8">${v?v+'k':'0'}</text>`).join('')}<polygon points="42,160 ${points(0)} 600,160" fill="url(#area-green)"/><polyline points="${points(1)}" fill="none" stroke="#91aaca" stroke-width="1.65" stroke-linejoin="round"/><polyline points="${points(0)}" fill="none" stroke="#489a79" stroke-width="1.8" stroke-linejoin="round"/>${labels.map((v,i)=>`<text x="${42+i*93}" y="184" text-anchor="middle" fill="#a9b4bc" font-size="7.5">${v}</text>`).join('')}<line id="chart-crosshair" x1="330" x2="330" y1="8" y2="160" stroke="#91b1a1" stroke-dasharray="3 3" style="display:none"/></svg><div class="chart-tooltip" id="chart-tooltip" hidden></div>`;
}
function clientTable(items,compact=false){return `<div class="table-wrap"><table><thead><tr><th>Client ID</th><th>状态</th><th>协议 / 入口</th>${compact?'':'<th>用户</th>'}<th>订阅</th><th>连接时长</th><th></th></tr></thead><tbody>${items.length?items.map(c=>`<tr data-client="${c.id}" tabindex="0" aria-label="查看 ${c.id} 详情"><td><div class="client-name"><span class="client-icon">${icon('plug')}</span><span class="mono">${c.id}</span></div><span class="row-sub mono">${c.ip}</span></td><td>${badge(c.online?'在线':'离线',c.online?'green':'gray',c.online)}</td><td><span class="mono">MQTT ${c.version}</span><span class="row-sub">WSS · mTLS</span></td>${compact?'':`<td>${c.user}</td>`}<td>${c.subscriptions}</td><td class="mono">${c.duration}</td><td><button class="icon-button" data-client="${c.id}" aria-label="查看连接详情">${icon('chevron')}</button></td></tr>`).join(''):'<tr><td colspan="7" class="empty-table">没有符合筛选条件的演示记录</td></tr>'}</tbody></table></div>`;}
function renderOverview(){return pageHeading('WORKSPACE / OVERVIEW','运行概览','了解 Broker 的连接、消息流量与运行状态。',`<span class="instance-state"><span class="status-dot"></span>运行正常</span><button class="btn" data-action="refresh">${icon('refresh')}<span class="hide-mobile">刷新数据</span></button>`)+metrics()+`
 <div class="two-column"><section class="panel">${panelTitle('消息吞吐',`<div class="segmented"><button data-range="1h" class="${state.range==='1h'?'active':''}">近 1 小时</button><button data-range="24h" class="${state.range==='24h'?'active':''}">近 24 小时</button></div>`)}<div class="chart-meta"><div><small><span class="legend-mark"></span>消息入站</small><b>${state.range==='1h'?'12,840':'10,260'}<span>条/s</span></b></div><div><small><span class="legend-mark blue"></span>消息出站</small><b>${state.range==='1h'?'18,296':'15,840'}<span>条/s</span></b></div></div><div class="traffic-chart" id="traffic-chart">${chart()}</div><div class="chart-bottom"><span>演示趋势</span><span>入站总量<b>${state.range==='1h'?'4,622 万':'8.86 亿'}</b></span><span>出站总量<b>${state.range==='1h'?'6,587 万':'13.69 亿'}</b></span></div></section>
 <section class="panel instance-panel">${panelTitle('实例信息',badge('单节点','gray'))}<div class="instance-body"><div class="instance-name"><span class="server-icon">${icon('server')}</span><div><b>broker-01</b><small>default / local workspace</small></div>${badge('运行中','green',true)}</div><dl class="kv-list"><dt>Broker 版本</dt><dd class="mono">0.1.0</dd><dt>运行时长</dt><dd>2 天 11 小时 36 分钟</dd><dt>连接入口</dt><dd class="mono">WSS :8084</dd><dt>会话存储</dt><dd>SQLite · WAL</dd><dt>协议版本</dt><dd class="mono">MQTT 3.1.1 / 5.0</dd></dl><div class="instance-tags">${badge('TLS 1.2 / 1.3','blue')}${badge('强制 mTLS','green')}${badge('QoS 0 / 1 / 2','gray')}</div></div></section></div>
 <div class="two-column"><section class="panel">${panelTitle('资源使用',`<span class="panel-subtitle">演示快照 · 14:32:08</span>`)}<div class="resource-row"><div><div class="resource-label">${icon('cpu')}CPU 使用率</div><div class="resource-value">24.8<small>%</small></div><div class="meter"><span style="width:24.8%"></span></div><div class="resource-note">4 vCPU · 实例总量</div></div><div><div class="resource-label">${icon('memory')}进程内存</div><div class="resource-value">1.24<small>/ 8 GiB</small></div><div class="meter"><span style="width:15.5%"></span></div><div class="resource-note">RSS / 示例内存上限</div></div><div><div class="resource-label">${icon('disk')}SQLite 数据</div><div class="resource-value">128.6<small>MiB</small></div><div class="meter"><span style="width:8%;background:#91aaca"></span></div><div class="resource-note">WAL 4.2 MiB · 持久化启用</div></div></div></section><section class="panel">${panelTitle('安全防护',`<button class="text-link" data-nav="security">查看策略 ${icon('arrow')}</button>`)}<div class="security-status"><div class="security-line"><span class="check-circle">✓</span>客户端证书验证<span class="muted">强制 mTLS</span></div><div class="security-line"><span class="check-circle">✓</span>匿名访问<span class="muted">已禁用</span></div><div class="security-line"><span class="check-circle">✓</span>认证限速<span class="muted">1,000 次/s</span></div><div class="security-line"><span class="check-circle">✓</span>认证并发上限<span class="muted">4 个任务</span></div></div></section></div>
 <section class="panel table-panel">${panelTitle('最近连接',`<button class="text-link" data-nav="connections">全部连接 ${icon('arrow')}</button>`,'最近 5 条演示记录')}${clientTable(clients.slice(0,5),true)}</section>`;}
function filteredClients(){return clients.filter(c=>(state.tab==='all'||(state.tab==='online'?c.online:!c.online))&&(state.version==='all'||c.version===state.version)&&(`${c.id} ${c.ip} ${c.user}`.toLowerCase().includes(state.search.toLowerCase())));}
function renderConnections(){const list=filteredClients(),pages=Math.max(1,Math.ceil(list.length/8));state.pageNumber=Math.min(state.pageNumber,pages);return pageHeading('MONITOR / CONNECTIONS','连接与会话','查看客户端连接、订阅与持久会话，按 Client ID、用户或 IP 筛选。',`<button class="btn" data-action="refresh">${icon('refresh')}刷新</button>`)+`<div class="summary-strip">${icon('users')}<span>在线连接 <b>8,462</b></span><span>离线会话 <b>889</b></span><small>下方展示 12 条可交互演示样例</small></div><section class="panel table-panel"><div class="table-tab">${[['all','全部样例','12'],['online','在线连接','10'],['offline','离线会话','2']].map(([key,title,count])=>`<button data-client-tab="${key}" class="${state.tab===key?'active':''}">${title}<span>${count}</span></button>`).join('')}</div><div class="filters"><div class="search-input">${icon('search')}<input id="client-search" placeholder="搜索 Client ID、用户或 IP" value="${escapeHtml(state.search)}" aria-label="筛选连接"></div><select id="version-filter" aria-label="筛选 MQTT 版本"><option value="all">全部协议版本</option><option value="5.0" ${state.version==='5.0'?'selected':''}>MQTT 5.0</option><option value="3.1.1" ${state.version==='3.1.1'?'selected':''}>MQTT 3.1.1</option></select><span class="filter-note">${icon('info')} 点击记录查看详情</span></div>${clientTable(list.slice((state.pageNumber-1)*8,state.pageNumber*8))}<div class="table-foot"><span>显示 ${(state.pageNumber-1)*8+(list.length?1:0)}–${Math.min(state.pageNumber*8,list.length)} 条，共 ${list.length} 条演示记录</span><div class="pagination">${Array.from({length:pages},(_,i)=>`<button data-page="${i+1}" class="${state.pageNumber===i+1?'active':''}" aria-label="第 ${i+1} 页">${i+1}</button>`).join('')}</div></div></section>`;}
function renderTopics(){const retained=state.topicTab==='retained',subscriptions=state.topicTab==='subscriptions';let rows;
 if(subscriptions)rows=[['devices/+/telemetry','platform-api','2',12,'MQTT5'],['devices/+/status','platform-api','1',8,'MQTT5'],['alerts/#','ops-reader','1',3,'MQTT5'],['devices/#','ops-reader','0',8,'MQTT 3.1.1']].map((r,i)=>`<tr><td class="topic-cell mono">${icon('topic')}${r[0]}</td><td>${r[1]}</td><td>${badge('QoS '+r[2],'gray')}</td><td>${r[3]}</td><td>${r[4]}</td><td><button class="text-link" data-topic="${i}" data-topic-type="subscription">查看</button></td></tr>`).join('');
 else rows=topics.slice(0,retained?3:6).map((r,i)=>`<tr><td class="topic-cell mono">${icon('topic')}${r[0]}<span class="row-sub">${r[4]}</span></td><td>${r[1]}</td><td>${retained?badge('QoS 1','gray'):r[2]}</td><td>${retained?'2026-10-30 14:31:52':r[3]}</td><td>${retained?badge('保留','green'):badge('活跃','green',true)}</td><td><button class="text-link" data-topic="${i}">查看消息</button></td></tr>`).join('');
 return pageHeading('MONITOR / TOPICS','主题与消息','查看主题、订阅过滤器与保留消息，了解消息的分发范围。')+`<section class="panel table-panel"><div class="table-tab">${[['active','活跃主题','6'],['subscriptions','订阅过滤器','4'],['retained','保留消息','3']].map(([id,title,n])=>`<button data-topic-tab="${id}" class="${state.topicTab===id?'active':''}">${title}<span>${n}</span></button>`).join('')}</div><div class="filters"><span class="muted" style="font-size:10px">${retained?'保留消息独立于会话；订阅时按过滤器回放。':subscriptions?'过滤器遵循 MQTT + / # 与系统主题匹配规则。':'演示实例中最近活跃的主题，消息内容可点击预览。'}</span></div><div class="table-wrap"><table><thead><tr><th>${subscriptions?'订阅过滤器':'Topic'}</th><th>用户</th><th>${subscriptions||retained?'QoS':'消息大小'}</th><th>${retained?'更新时间':'订阅数'}</th><th>${subscriptions?'协议':'状态'}</th><th></th></tr></thead><tbody>${rows}</tbody></table></div></section>`;
}
function renderSecurity(){let content='';if(state.securityTab==='users')content=`<div class="filters"><span class="muted" style="font-size:10px">本地策略文件 · Argon2id 密码验证 · 未授权操作默认拒绝</span><button class="btn toolbar-right" data-action="policy">${icon('rule')}查看策略示例</button></div><div class="table-wrap"><table><thead><tr><th>用户</th><th>Client ID 前缀</th><th>发布权限</th><th>订阅 / 接收权限</th><th>来源</th></tr></thead><tbody>${[['device-service','sensor-','devices/#','devices/+/commands'],['platform-api','platform-','platform/#, alerts/#','devices/#'],['ops-reader','ops-','—','devices/#, alerts/#']].map(r=>`<tr><td><span class="client-name">${icon('users')}${r[0]}</span></td><td class="mono">${r[1]}</td><td class="mono">${r[2]}</td><td class="mono">${r[3]}</td><td>${badge('本地 JSON','gray')}</td></tr>`).join('')}</tbody></table></div><div class="panel-body"><div class="note">演示规则用于展示页面。身份认证、Client ID 约束、发布 / 订阅授权分别检查；证书验证不会替代 MQTT 用户权限。</div></div>`;
 if(state.securityTab==='admission')content=`<div class="panel-body">${[['并发握手上限','max_handshakes','TLS / HTTP 升级 / 初始认证至 CONNACK 写出','128'],['认证后台任务','max_auth_tasks','任务取消后仍保留额度，直到后台工作结束','4'],['认证速率','auth_rate_per_second','全局 CONNECT / AUTH 尝试令牌，每秒补充','1,000 次/s'],['突发容量','auth_burst','认证令牌桶容量；正常 PING / PUBLISH / ACK 不扣费','1,000']].map(r=>`<div class="config-row"><div><b>${r[0]}</b><p>${r[2]}</p></div><div class="config-value">${r[3]}<small>${r[1]}</small></div></div>`).join('')}<div class="note">配置启动时加载。初始超额返回 CONNACK 3 / 0x89，重新认证超额使用 DISCONNECT 0x97；已有会话不会被被拒绝的连接接管。</div></div>`;
 if(state.securityTab==='certificates')content=`<div class="panel-body"><div class="summary-strip" style="margin:0 0 15px">${icon('certificate')}<span>客户端证书验证 <b>强制 mTLS</b></span></div><dl class="kv-list"><dt>TLS 版本</dt><dd class="mono">TLS 1.2 / TLS 1.3</dd><dt>加密实现</dt><dd>rustls · ring</dd><dt>服务端证书示例路径</dt><dd class="mono">/etc/lyrnormq/tls/server-chain.pem</dd><dt>客户端 CA 示例路径</dt><dd class="mono">/etc/lyrnormq/tls/client-ca.pem</dd><dt>证书身份映射</dt><dd>未启用</dd><dt>MQTT 认证 / ACL</dt><dd>独立执行</dd></dl><div class="note">当前页面为设计样例，未读取真实证书。信任链、有效期、用途与私钥证明在 TLS 握手时校验。证书与 CA 在启动时加载，热更新尚未实现。</div></div>`;
 return pageHeading('MANAGE / ACCESS CONTROL','认证与授权','管理身份来源、Topic 权限与连接保护策略。',`<button class="btn" data-action="launch">${icon('rule')}启动配置</button>`)+`<div class="detail-grid"><div class="card detail-card"><div class="detail-card-top"><span class="card-icon">${icon('users')}</span>${badge('本地策略','gray')}</div><h3>用户身份</h3><div class="detail-card-number">3 <small class="muted" style="font-size:10px;font-weight:400">个演示用户</small></div><p>Argon2id · 匿名访问已禁用</p></div><div class="card detail-card"><div class="detail-card-top"><span class="card-icon">${icon('shield')}</span>${badge('保护启用','green')}</div><h3>认证保护</h3><div class="detail-card-number">1,000 <small class="muted" style="font-size:10px;font-weight:400">次 / 秒</small></div><p>突发容量 1,000 · 4 个认证任务</p></div><div class="card detail-card"><div class="detail-card-top"><span class="card-icon">${icon('certificate')}</span>${badge('强制验证','green')}</div><h3>传输信任</h3><div class="detail-card-number">mTLS</div><p>WSS · TLS 1.2 / 1.3 · rustls</p></div></div><section class="panel table-panel"><div class="table-tab">${[['users','用户与权限'],['admission','认证保护'],['certificates','证书策略']].map(([id,title])=>`<button data-security-tab="${id}" class="${state.securityTab===id?'active':''}">${title}</button>`).join('')}</div>${content}</section>`;
}
const launchCommand='lyrnormq --listen 0.0.0.0:8084 --websocket \\\n  --tls-cert /etc/lyrnormq/tls/server-chain.pem \\\n  --tls-key /etc/lyrnormq/tls/server-key.pem \\\n  --tls-client-ca /etc/lyrnormq/tls/client-ca.pem \\\n  --auth-policy /etc/lyrnormq/policy.json \\\n  --max-connections 10000 --max-sessions 10000 \\\n  --max-handshakes 128 --max-auth-tasks 4 \\\n  --auth-rate-per-second 1000 --auth-burst 1000';
function renderListeners(){return pageHeading('MANAGE / LISTENER','连接入口','当前单进程选择一种监听方式；下方为可选传输的设计展示。',`<button class="btn" data-action="launch">${icon('copy')}查看启动参数</button>`)+`<div class="listener-grid">${[['TCP','1883','未选择'],['TLS','8883','未选择'],['WS','8083','未选择'],['WSS','8084','演示配置']].map(([type,port,label])=>`<section class="card detail-card listener-card ${type==='WSS'?'':'inactive'}"><div class="detail-card-top"><span class="card-icon">${icon(type==='TLS'||type==='WSS'?'shield':'plug')}</span>${badge(label,type==='WSS'?'green':'gray')}</div><h3>${type}</h3><div class="detail-card-number mono">:${port}</div><p>${type==='WS'||type==='WSS'?'路径 /mqtt · 子协议 mqtt':'MQTT 3.1.1 / 5.0'}</p></section>`).join('')}</div><div class="section-grid"><section class="panel">${panelTitle('当前入口',badge('示例配置','green'))}<div class="panel-body"><dl class="kv-list"><dt>监听地址</dt><dd class="mono">0.0.0.0:8084</dd><dt>传输协议</dt><dd>MQTT over WSS</dd><dt>WebSocket 路径</dt><dd class="mono">/mqtt</dd><dt>WebSocket 消息上限</dt><dd>1 MiB</dd><dt>客户端证书</dt><dd>必须提供</dd><dt>MQTT 协议</dt><dd class="mono">3.1.1 / 5.0</dd></dl></div></section><section class="panel">${panelTitle('连接生命周期')}<div class="panel-body"><ul class="timeline" style="padding:0"><li><span class="check-circle">1</span><div><b>额度检查</b><small>总连接与并发握手名额</small></div></li><li><span class="check-circle">2</span><div><b>TLS / mTLS 与 HTTP 升级</b><small>验证证书并协商 mqtt 子协议</small></div></li><li><span class="check-circle">3</span><div><b>MQTT 认证与权限</b><small>认证限速 → 用户验证 → 会话归属</small></div></li><li><span class="check-circle">4</span><div><b>CONNACK 完成</b><small>释放握手名额，进入正常消息收发</small></div></li></ul></div></section></div><div class="note">四种入口是互斥的启动选项，并非四个同时运行的监听器。多监听共享状态尚未实现。</div>`;}
function renderConfiguration(){return pageHeading('MANAGE / CONFIGURATION','实例配置','查看启动参数与资源边界。设计稿中的数值为示例配置。',`<button class="btn" data-action="launch">${icon('copy')}启动参数</button>`)+`<section class="panel">${panelTitle('连接与消息')}<div class="panel-body">${[['总连接上限','max_connections','10,000','所有已接入连接，包括正在握手的连接'],['会话上限','max_sessions','10,000','在线与持久离线会话'],['MQTT 包大小','max_packet_size','64 KiB','单个解码 MQTT 报文'],['出站队列容量','outbound_capacity','64','每会话排队上限'],['QoS 窗口','max_inflight','32','QoS1 / QoS2 inflight 额度'],['握手超时','handshake_timeout','10,000 ms','TLS、HTTP、MQTT 各阶段的超时'],['写入超时','write_timeout','5,000 ms','包含 flush 与有界关闭收尾']].map(([label,key,value,note])=>`<div class="config-row"><div><b>${label}</b><p>${note}</p></div><div class="config-value">${value}<small>${key}</small></div></div>`).join('')}<div class="note">当前 Broker 配置在进程启动时加载，此页先展示只读设计。修改、校验和重启流程需后续管理 API 接入。</div></div></section>`;}
function renderLogs(){const rows=events.filter(e=>state.logLevel==='all'||e[1]===state.logLevel);return pageHeading('MONITOR / EVENTS','事件记录','以时间线查看连接、认证、会话恢复与存储事件。')+`<section class="panel"><div class="log-toolbar"><span>2026-10-30 · 演示事件</span><select id="log-filter" aria-label="筛选事件级别"><option value="all">全部级别</option><option value="INFO" ${state.logLevel==='INFO'?'selected':''}>INFO</option><option value="WARN" ${state.logLevel==='WARN'?'selected':''}>WARN</option></select></div>${rows.map(e=>`<div class="log-line"><time>${e[0]}</time><span class="log-level ${e[1]==='WARN'?'warn':''}">${e[1]}</span><span><b>${e[2]}</b>  ${e[3]}<br><span class="muted">${e[4]}</span></span></div>`).join('')}</section><div class="note">这是用于确认日志信息层级的演示记录，尚未接入 Broker 日志或管理接口。</div>`;}
function renderRules(){return pageHeading('EXTENSIONS / RULE ENGINE','规则引擎','以 SQL 描述消息筛选与转换，独立配置后续动作。',badge('规划中','gray'))+`<section class="panel"><div class="blank-state"><span class="blank-icon">${icon('rule')}</span><h2>让消息成为可执行的数据流</h2><p>规则引擎目前处于设计阶段。页面预留 SQL 编辑、样例测试与动作配置的位置，暂不执行规则。</p><div class="rule-flow"><span>Topic 匹配</span><i>→</i><span>SQL 筛选 / 转换</span><i>→</i><span>动作执行</span></div></div><div class="panel-body" style="padding-top:0"><div class="label">SQL 设计示例 · 尚未接入执行引擎</div><pre class="code-block"><span class="sql-keyword">SELECT</span> clientid, payload.temperature <span class="sql-keyword">AS</span> temperature
<span class="sql-keyword">FROM</span> "devices/+/telemetry"
<span class="sql-keyword">WHERE</span> payload.temperature &gt; 80</pre><div class="pill-group">${badge('MQTT 重发布','gray')}${badge('HTTP Webhook','gray')}${badge('可靠重试','gray')}</div></div></section>`;}
function render(){document.getElementById('navigation').innerHTML=nav.map(([title,items])=>`<div class="nav-group-title">${title}</div>${items.map(([id,ic,label,tag])=>`<a class="nav-link ${state.page===id?'active':''}" href="#${id}" ${state.page===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${tag?`<span class="${tag==='规划中'?'nav-tag':'nav-count'}">${tag}</span>`:''}</a>`).join('')}`).join('');const renders={overview:renderOverview,connections:renderConnections,topics:renderTopics,security:renderSecurity,listeners:renderListeners,configuration:renderConfiguration,logs:renderLogs,rules:renderRules};document.getElementById('main').innerHTML=(renders[state.page]||renderOverview)();document.title=`${nav.flatMap(x=>x[1]).find(x=>x[0]===state.page)?.[2]||'概览'} · lyrnormq`;bindControls();}
function navigate(page){if(location.hash===`#${page}`){state.page=page;render();}else location.hash=page;document.getElementById('sidebar').classList.remove('open');}
function kv(items){return `<dl class="kv-list">${items.map(([k,v])=>`<dt>${k}</dt><dd>${v}</dd>`).join('')}</dl>`;}
function openDrawer(title,subtitle,body){if(document.getElementById('drawer').hidden)previousFocus=document.activeElement;document.getElementById('overlay').hidden=false;const el=document.getElementById('drawer');el.innerHTML=`<div class="drawer-head"><div><h2 id="drawer-title">${title}</h2><p>${subtitle}</p></div><button class="icon-button" data-action="close-drawer" aria-label="关闭详情">${icon('close')}</button></div><div class="drawer-body">${body}</div>`;el.hidden=false;document.body.style.overflow='hidden';el.querySelector('button')?.focus();}
function closeDrawer(){document.getElementById('overlay').hidden=true;document.getElementById('drawer').hidden=true;document.body.style.overflow='';previousFocus?.focus();}
function clientDetail(id){const c=clients.find(x=>x.id===id);if(!c)return;openDrawer('连接与会话详情',c.id,`<div class="pill-group">${badge(c.online?'在线':'离线',c.online?'green':'gray',c.online)}${badge('MQTT '+c.version,'blue')}${badge('WSS · mTLS','green')}</div><h3 class="drawer-section">客户端</h3>${kv([['Client ID',`<span class="mono">${c.id}</span>`],['来源 IP',`<span class="mono">${c.ip}</span>`],['用户',c.user],['身份',`<span class="mono">user:${c.user}</span>`],['连接时长',c.duration],['客户端证书','已通过验证（演示）']])}<h3 class="drawer-section">会话与消息</h3>${kv([['持久会话','是'],['会话有效期',c.version==='5.0'?'3,600 秒':'持久保留（MQTT 3.1.1）'],['订阅数量',c.subscriptions],['消息入站',c.incoming.toLocaleString()],['消息出站',c.outgoing.toLocaleString()],['离线排队',c.queued+' 条'],[c.version==='5.0'?'Receive Maximum':'出站 QoS 窗口',c.version==='5.0'?'32':'32（本地配置）']])}<button class="btn" data-copy="${c.id}">${icon('copy')}复制 Client ID</button><div class="note">详情来自本地样例。连接管理与断开操作尚未接入真实 Broker。</div>`);}
function topicDetail(index,type){if(type==='subscription'){const filter=['devices/+/telemetry','devices/+/status','alerts/#','devices/#'][index];openDrawer('订阅过滤器',filter,`${kv([['过滤器',`<span class="mono">${filter}</span>`],['匹配规则','MQTT Topic Filter'],['No Local','关闭'],['Retain As Published','按订阅选项'],['共享订阅','否']])}<div class="note">订阅过滤器、共享组与消息交付参数将在此展示。</div>`);return;}const row=topics[index];const payload={device_id:row[0].split('/')[1],temperature:26.8,humidity:61,status:'online',timestamp:'2026-10-30T06:31:52Z'};openDrawer('消息预览',row[0],`${kv([['Topic',`<span class="mono">${row[0]}</span>`],['用户',row[1]],['QoS','1'],['Retain',state.topicTab==='retained'?'是':'否'],['Payload 格式','JSON']])}<h3 class="drawer-section">演示 Payload</h3><pre class="code-block">${escapeHtml(JSON.stringify(payload,null,2))}</pre><div class="note">预览为合成示例，未订阅或读取真实业务消息。</div>`);}
function openGlobalSearch(){
 openDrawer('搜索工作空间','连接、会话与主题 · 演示数据',`<div class="search-input" style="max-width:none">${icon('search')}<input id="workspace-query" placeholder="输入 Client ID、用户、IP 或 Topic" aria-label="搜索工作空间"></div><div id="workspace-results"></div>`);
 const input=document.getElementById('workspace-query');
 function results(){const q=input.value.toLowerCase(),matchedClients=clients.filter(c=>`${c.id} ${c.user} ${c.ip}`.toLowerCase().includes(q)),matchedTopics=topics.map((t,i)=>({t,i})).filter(x=>x.t[0].toLowerCase().includes(q));
 document.getElementById('workspace-results').innerHTML=`<div class="label">连接与会话 · ${matchedClients.length} 条${matchedClients.length>5?'（显示前 5 条）':''}</div>${matchedClients.slice(0,5).map(c=>`<button class="search-result" data-client="${c.id}">${icon('users')}<span>${c.id}<small>${c.user} · ${c.online?'在线':'离线'}</small></span>${icon('chevron')}</button>`).join('')||'<div class="search-empty">没有匹配的连接</div>'}<div class="label">主题 · ${matchedTopics.length} 条${matchedTopics.length>5?'（显示前 5 条）':''}</div>${matchedTopics.slice(0,5).map(({t,i})=>`<button class="search-result" data-topic="${i}">${icon('topic')}<span>${t[0]}<small>${t[4]}</small></span>${icon('chevron')}</button>`).join('')||'<div class="search-empty">没有匹配的主题</div>'}`;}
 input.addEventListener('input',results);results();input.focus();
}
function showLaunch(){openDrawer('启动配置','WSS + mTLS · 示例参数',`<div class="note" style="margin-top:0">证书和策略路径为示例，请按部署环境调整。此原型不修改 Broker 配置。</div><pre class="code-block">${escapeHtml(launchCommand)}</pre><button class="btn" data-action="copy-launch">${icon('copy')}复制示例命令</button>`);}
function showPolicy(){openDrawer('本地策略示例','认证与 Topic ACL',`<div class="note" style="margin-top:0">以下只展示权限结构。实际 policy.json 还需有效 Argon2id password_hash；此处不展示或生成密码。</div><pre class="code-block">${escapeHtml(JSON.stringify({allow_anonymous:false,users:[{username:'device-service',password_hash:'<Argon2id PHC>',client_id_prefix:'sensor-',publish:['devices/#'],subscribe:['devices/+/commands']}]},null,2))}</pre>`);}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('已复制到剪贴板');}catch{openDrawer('复制内容','当前浏览器未开放剪贴板权限',`<pre class="code-block">${escapeHtml(text)}</pre>`);}}
function bindControls(){document.getElementById('client-search')?.addEventListener('input',e=>{const position=e.target.selectionStart;state.search=e.target.value;state.pageNumber=1;render();const el=document.getElementById('client-search');el.focus();el.setSelectionRange(position,position);});document.getElementById('version-filter')?.addEventListener('change',e=>{state.version=e.target.value;state.pageNumber=1;render();});document.getElementById('log-filter')?.addEventListener('change',e=>{state.logLevel=e.target.value;render();});document.getElementById('traffic-chart')?.addEventListener('pointermove',e=>{const box=e.currentTarget.getBoundingClientRect(),ratio=Math.max(0,Math.min(1,(e.clientX-box.left-35)/(box.width-60)));const line=document.getElementById('chart-crosshair');line.style.display='';line.setAttribute('x1',42+558*ratio);line.setAttribute('x2',42+558*ratio);const tip=document.getElementById('chart-tooltip');tip.hidden=false;tip.style.left=Math.min(box.width-128,Math.max(40,e.clientX-box.left+12))+'px';const i=Math.round(ratio*60),sample=trafficSamples()[i],date=new Date(Date.UTC(2026,9,30,14,30)-(1-i/60)*(state.range==='1h'?3600000:86400000));const time=`${date.getUTCMonth()+1}/${date.getUTCDate()} ${String(date.getUTCHours()).padStart(2,'0')}:${String(date.getUTCMinutes()).padStart(2,'0')}`;tip.innerHTML=`演示采样 ${time}<br>入站 ${Math.round(sample[0]*1000).toLocaleString()} 条/s<br>出站 ${Math.round(sample[1]*1000).toLocaleString()} 条/s`;});document.getElementById('traffic-chart')?.addEventListener('pointerleave',()=>{document.getElementById('chart-tooltip').hidden=true;document.getElementById('chart-crosshair').style.display='none';});}
document.addEventListener('click',e=>{const el=e.target.closest('button,[data-client]');if(!el)return;if(el.dataset.client){clientDetail(el.dataset.client);return;}if(el.dataset.nav){navigate(el.dataset.nav);return;}if(el.dataset.range){state.range=el.dataset.range;render();return;}if(el.dataset.clientTab){state.tab=el.dataset.clientTab;state.pageNumber=1;render();return;}if(el.dataset.topicTab){state.topicTab=el.dataset.topicTab;render();return;}if(el.dataset.securityTab){state.securityTab=el.dataset.securityTab;render();return;}if(el.dataset.page){state.pageNumber=+el.dataset.page;render();return;}if(el.dataset.topic!==undefined){topicDetail(+el.dataset.topic,el.dataset.topicType);return;}if(el.dataset.copy){copy(el.dataset.copy);return;}switch(el.dataset.action){case'close-drawer':closeDrawer();break;case'refresh':toast('演示数据已刷新 · 未连接真实实例');break;case'launch':showLaunch();break;case'policy':showPolicy();break;case'copy-launch':copy(launchCommand);}});
document.getElementById('overlay').addEventListener('click',closeDrawer);
document.getElementById('global-search').addEventListener('click',openGlobalSearch);
document.getElementById('profile-button').addEventListener('click',()=>openDrawer('当前工作空间','本地设计预览',`${kv([['工作空间','默认工作空间'],['实例','broker-01'],['当前访问','原型浏览'],['数据来源','本地合成样例']])}<div class="note">Dashboard 登录、管理权限与 API 尚未实现，此页面不连接 Broker。</div>`));
document.getElementById('mobile-menu').innerHTML=icon('menu');document.getElementById('mobile-menu').addEventListener('click',()=>document.getElementById('sidebar').classList.toggle('open'));
document.getElementById('search-icon').innerHTML=icon('search');
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeDrawer();document.getElementById('sidebar').classList.remove('open');}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openGlobalSearch();}if(e.key==='Enter'&&e.target.matches('tr[data-client]'))clientDetail(e.target.dataset.client);if(e.key==='Tab'&&!document.getElementById('drawer').hidden){const focusable=[...document.getElementById('drawer').querySelectorAll('button,a,input,select,textarea')];const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('hashchange',()=>{const page=location.hash.slice(1);state.page=nav.flatMap(x=>x[1]).some(x=>x[0]===page)?page:'overview';render();window.scrollTo(0,0);});
state.page=nav.flatMap(x=>x[1]).some(x=>x[0]===location.hash.slice(1))?location.hash.slice(1):'overview';render();
